 dict(id=25,slug='zoo-dino-pigment-evidence',title='A color clue, not a photo',hook='Some preserved structures constrain reconstructions.',question='A fossil preserves structures interpreted as pigment-bearing organelles. What can this evidence do for a color reconstruction?',options=['Constrain some possibilities, subject to analysis','Prove the exact appearance of every body part','Show the entire animal in a color photograph'],why='In this schematic, the dark marks stand for preserved structures being compared with a reference. Such evidence can constrain some color hypotheses, but preservation and interpretation limit what is known about the whole animal.',recallq='A fossil preserves a local color-related microscopic structure. Does that automatically reveal the exact color of every body part?',recallo=['No, it constrains only what the evidence supports','Yes, every part is fully known','Yes, it is a color photograph'],recallwhy='Local preservation does not automatically establish an entire animal’s appearance.',left='<path d="M36 112 Q82 32 132 112" stroke="var(--muted)" strokeWidth="3" fill="#bfc8bb"/><circle cx="72" cy="91" r="5" fill="#342c2a"/><circle cx="85" cy="80" r="5" fill="#342c2a"/><circle cx="97" cy="90" r="5" fill="#342c2a"/><text x="80" y="157" fill="var(--fg)" fontSize="12" textAnchor="middle">Preserved structures</text>',right='<rect x="203" y="52" width="114" height="74" rx="12" fill="var(--bg-2)" stroke="var(--muted)" strokeWidth="2"/><circle cx="230" cy="88" r="5" fill="var(--warn)"/><circle cx="246" cy="88" r="5" fill="var(--warn)"/><text x="280" y="94" fill="var(--fg)" fontSize="20">?</text><text x="260" y="157" fill="var(--fg)" fontSize="12" textAnchor="middle">Reference comparison</text>',caption='Schematic; inference depends on preservation'),
 dict(id=26,slug='zoo-dino-plates-in-place',title='Where did the plate go?',hook='A fossil can preserve more than separate parts.',question='In a toy fossil comparison, which arrangement gives a clearer clue about where a plate belonged?',options=['A plate preserved beside connected bones','A lone plate without nearby bones','Both give equally specific placement evidence'],why='The connected bones and neighboring plate remain together in the first schematic, providing more context for placement. An isolated plate can still be informative, but its position is not directly preserved in that example.',recallq='A bone is found beside connected body fossils rather than alone. What extra clue might the context provide?',recallo=['Its position relative to the other remains','The animal’s exact original color','The date of every related species'],recallwhy='Associated remains can preserve relationships among parts.',left='<path d="M25 108 H135 M38 108 V83 M57 108 V84 M76 108 V84 M95 108 V84 M114 108 V84" stroke="#dbcaa9" strokeWidth="5"/><path d="M67 78 L80 48 L94 78Z" fill="#d0a88b" stroke="var(--muted)" strokeWidth="2"/><text x="80" y="155" fill="var(--fg)" fontSize="12" textAnchor="middle">Associated parts</text>',right='<path d="M246 120 L260 62 L276 120Z" fill="#d0a88b" stroke="var(--muted)" strokeWidth="2"/><text x="260" y="155" fill="var(--fg)" fontSize="12" textAnchor="middle">Isolated plate</text>',caption='Toy fossil contexts; not a specimen record'),
