# Source leads only; independent fact-checking must select precise sources and specimens.
MISCONCEPTIONS={7: 'A hollow bone alone proves an animal could fly.', 13: 'Animals with very different appearances cannot share a dinosaur subgroup.', 14: 'A worn tooth alone shows whether a replacement was developing.', 22: 'A body-mass estimate is independent of the assumed body volume.', 23: 'Distance alone determines speed without a time interval.', 25: 'A local pigment clue establishes the exact appearance of an entire animal.', 26: 'An isolated fossil preserves the same placement context as associated remains.', 29: 'A jaw joint places no constraint on modeled jaw motion.', 30: 'Equal weights balance at arbitrary distances from a pivot.', 32: 'A single fragment exposes as much whole-body anatomy as a more complete skeleton.', 33: 'A new character cannot change which grouping is supported.', 39: 'A plant fossil in a deposit proves the animal’s exact behavior.', 40: 'Present-day geography alone is sufficient for every deep-time fossil comparison.', 45: 'Tracks on different surfaces must have been made simultaneously.'}
SOURCE='Unverified research starting points: Smithsonian National Museum of Natural History, https://naturalhistory.si.edu/collections/paleobiology ; University of California Museum of Paleontology, https://ucmp.berkeley.edu/ . Claim-specific references and specimen evidence have not been checked.'
assert len(C)==14 and len({c['id'] for c in C})==14 and len({c['slug'] for c in C})==14
existing=[c['slug'] for c in C if (Path('src/demos/life')/c['slug']).exists()]
if existing: raise SystemExit('Refusing to overwrite existing lessons: '+', '.join(existing))
T='''"use client";
import { useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
type LessonData = {question:string; options:string[]; answer:number; why:string; caption:string; leftDescription:string};
const d:LessonData = __DATA__;
export default function Demo({slug}:{slug:string}){
 const [step,setStep]=useState(0);
 return <Lesson slug={slug} predict={{question:d.question,options:d.options,answer:d.answer}} exploreHint="Inspect both sides of the schematic." reveal={()=><p>{d.why}</p>}>
 {({locked,interact})=><div><svg className="stage-svg" viewBox="0 0 340 180" role="img" aria-label={step===0?"Evidence hidden until inspection":step===1?d.leftDescription:d.why}>
 {step>=1&&<g>__LEFT__</g>}
 {step>=2&&<g>__RIGHT__</g>}
 </svg><Row><Control style={{minHeight:44,minWidth:44}} disabled={locked||step!==0} onClick={()=>setStep(1)}>Inspect first</Control><Control style={{minHeight:44,minWidth:44}} disabled={locked||step!==1} onClick={()=>{setStep(2);interact()}}>Inspect second</Control></Row><p style={{textAlign:"center",color:"var(--muted)",fontSize:".8rem"}}>{d.caption}</p></div>}
 </Lesson>;
}
'''
manifest=[]
for c in C:
 n=c['id']; slug=c['slug']; shift=n%3
 opts=c['options'][shift:]+c['options'][:shift]; answer=opts.index(c['options'][0])
 ro=c['recallo'][shift:]+c['recallo'][:shift]; ra=ro.index(c['recallo'][0])
 labels='; '.join(re.findall(r'>([^<>]+)</text>',c['left']))
 data={'question':c['question'],'options':opts,'answer':answer,'why':c['why'],'caption':c['caption'],'leftDescription':'First side: '+labels+'. Second side hidden.'}
 demo=T.replace('__DATA__',json.dumps(data,ensure_ascii=False,indent=2)).replace('__LEFT__',c['left']).replace('__RIGHT__',c['right'])
 out=Path('src/demos/life')/slug;out.mkdir(parents=True)
 (out/'Demo.tsx').write_text(demo)
 meta={'slug':slug,'title':c['title'],'hook':c['hook'],'domain':'life','concept':slug,'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Fossils and models can supply evidence about the past.'],'doesNotKnow':[c['why']]},'misconception':MISCONCEPTIONS[n],'objective':c['question'],'claims':[{'id':f'life.{slug}.c1','text':c['hook']+' '+c['question']+' '+c['why'],'support':'source','source':SOURCE,'status':'unverified'},{'id':f'life.{slug}.c2','text':'Diagram convention: '+c['caption']+' Diagram labels: '+'; '.join(re.findall(r'>([^<>]+)</text>',c['left']+c['right']))+'.','support':'convention','source':'Explicitly labeled schematic; not a specimen reconstruction.','status':'unverified'},{'id':f'life.{slug}.c3','text':'Recall: '+c['recallq']+' '+c['recallwhy'],'support':'source','source':SOURCE,'status':'unverified'}],'confidence':'','recall':{'question':c['recallq'],'options':ro,'answer':ra,'why':c['recallwhy']},'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 (out/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
 review=Path('company/reviews')/slug;review.mkdir(parents=True)
 (review/'build.md').write_text(f'''# {slug}: build note, 2026-10-28\n\nDraft v1 for proposed curriculum item {n:03d}. The figure is a hand-authored schematic; the two-state stage is an illustration, not an independently modeled simulation. All claim-specific citations, specimen anatomy and scientific implications require independent verification.\n\n## Pre-flight v1\n\n1. Title and hook: “{c['title']}” / “{c['hook']}”; ask an independent reviewer to assess answer cues.\n2. Options: {', '.join(opts)}.\n3. The locked stage hides both diagram sides; controls are disabled until prediction.\n4. The second action exposes the complete comparison and enables reveal. Both shown sides remain visible at reveal; check that the drawing demonstrates the wording.\n5. QA path: Inspect first, then Inspect second. This is code inspection, not a browser verdict.\n6. No in-stage reset is provided; reload behavior is untested.\n7. Strict phone fit, contrast, actual control dimensions, keyboard behavior, visual pedagogy and browser contract have not been checked.\n\nExact supporting sources, overlap with the existing catalog, accessibility, scientific accuracy, image legibility and learner review remain open.\n''')
 manifest.append({'plan_id':n,'slug':slug})
Path('company/reviews/zoology-dino-extra/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('Built',len(C),'distinct diagram prompts:', ', '.join(str(x['id']) for x in C))
